    } else if (e?.type === 'system' && e?.subtype === 'stop_hook_summary') {
      out.push({ kind: 'hook', text: (e.hookErrors ?? []).join('\n') });
    } else if (e?.type === 'attachment' && e?.attachment?.hookEvent === 'Stop') {
      out.push({ kind: 'hook', text: `${e.attachment.stderr ?? ''}\n${e.attachment.stdout ?? ''}` });
