  const bs = blobs(entries);
  const seen = new Set();
  const runs = { work: { runs: 0, failures: 0, errors: 0, blocking: 0, advisory: 0 }, world: { runs: 0, failures: 0, errors: 0, blocking: 0, advisory: 0 } };
  const rules = {};
