    if (b.kind === 'bash') {
      const inv = { work: 0, world: 0 };
      for (const m of b.command.matchAll(INVOKE_RE)) inv[m[1]] += 1;
      const rep = { work: 0, world: 0 };
      for (const m of summaries) rep[m[3]] += 1;
      const fail = { work: 0, world: 0 };
      for (const m of summaries) if (Number(m[1]) > 0) fail[m[3]] += 1;
      for (const scope of ['work', 'world']) {
